<script setup lang="ts">
import type { ReferenceOption } from '@/business/references'
import type { Field } from '@/business/model'
import { initial } from '@/business/model'
const props=defineProps<{fields:Field[];modelValue:Record<string,unknown>;root?:Record<string,unknown>;prefix?:string;disabled?:boolean;references?:Record<string,ReferenceOption[]>;referenceBusy?:boolean;errors?:Record<string,string>}>()
const emit=defineEmits<{ 'update:modelValue':[Record<string,unknown>];'read-reference':[{field:Field;context:Record<string,unknown>;key:string}];'reference-selected':[{field:Field;record:Record<string,unknown>;key:string}] }>()
const change=(key:string,value:unknown)=>emit('update:modelValue',{...props.modelValue,[key]:value})
const object=(v:unknown):Record<string,unknown>=>v&&typeof v==='object'&&!Array.isArray(v)?v as Record<string,unknown>:{}
const list=(v:unknown):Record<string,unknown>[]=>Array.isArray(v)?v as Record<string,unknown>[]:[]
const pick=(f:Field,e:Event)=>{const value=(e.target as HTMLSelectElement).value;change(f.key,value);const r=props.references?.[inputId(f)]?.find(r=>r.value===value);if(r)emit('reference-selected',{field:f,record:r.record,key:inputId(f)})}
const inputId=(f:Field)=>`${props.prefix||'business'}-${f.key}`
const accessibility=(f:Field)=>({'aria-invalid':props.errors?.[inputId(f)]?true:undefined,'aria-describedby':props.errors?.[inputId(f)]?`${inputId(f)}-error`:undefined})
const selectedReference=(f:Field)=>props.references?.[inputId(f)]?.find(r=>r.value===props.modelValue[f.key])
const label=(v:string|readonly[string,string])=>typeof v==='string'?v:v[1]
const choice=(v:string|readonly[string,string])=>typeof v==='string'?v:v[0]
const toggleId=(f:Field,v:string,checked:boolean)=>{const a=String(props.modelValue[f.key]||'').split(/[\s,，]+/).filter(Boolean);change(f.key,(checked?[...new Set([...a,v])]:a.filter(x=>x!==v)).join('\n'))}
const toggle=(f:Field,v:string,checked:boolean)=>{const a=Array.isArray(props.modelValue[f.key])?props.modelValue[f.key] as string[]:[];change(f.key,checked?[...new Set([...a,v])]:a.filter(x=>x!==v))}
</script>
<template><template v-for="f in fields" :key="f.key"><div v-if="!f.visible||f.visible(root||modelValue)" :id="`${inputId(f)}-field`" class="business-control" :class="{'has-error':errors?.[inputId(f)]}" tabindex="-1">
<fieldset v-bind="accessibility(f)" v-if="f.type==='group'" class="business-group"><legend>{{f.label}}</legend><label v-if="f.nullable" class="trade-check"><input v-bind="accessibility(f)" type="checkbox" :disabled="disabled||f.readonly" :checked="modelValue[f.key]!=null" @change="change(f.key,($event.target as HTMLInputElement).checked?initial(f.fields||[]):null)">填写此项</label><BusinessFields v-if="!f.nullable||modelValue[f.key]!=null" :fields="f.fields||[]" :model-value="object(modelValue[f.key])" :root="root||modelValue" :prefix="inputId(f)" :disabled="disabled||f.readonly" :references="references" :reference-busy="referenceBusy" :errors="errors" @read-reference="emit('read-reference',$event)" @reference-selected="emit('reference-selected',$event)" @update:model-value="change(f.key,$event)"/></fieldset>
<fieldset v-bind="accessibility(f)" v-else-if="f.type==='list'" class="business-group"><legend>{{f.label}}</legend><div v-for="(row,i) in list(modelValue[f.key])" :key="i" class="business-repeat"><h3>{{f.label}} {{i+1}}</h3><BusinessFields :fields="f.fields||[]" :model-value="row" :root="root||modelValue" :prefix="`${inputId(f)}-${i}`" :disabled="disabled||f.readonly" :references="references" :reference-busy="referenceBusy" :errors="errors" @read-reference="emit('read-reference',$event)" @reference-selected="emit('reference-selected',$event)" @update:model-value="change(f.key,list(modelValue[f.key]).map((r,j)=>j===i?$event:r))"/><button type="button" class="outline" :disabled="disabled||f.readonly" @click="change(f.key,list(modelValue[f.key]).filter((_,j)=>j!==i))">移除此项</button></div><button type="button" class="outline" :disabled="disabled||list(modelValue[f.key]).length>=(f.max||20)" @click="change(f.key,[...list(modelValue[f.key]),initial(f.fields||[])])">添加{{f.label}}</button></fieldset>
<fieldset v-bind="accessibility(f)" v-else-if="f.type==='ids'" class="business-group"><legend>{{f.label}}</legend><label v-for="r in (references?.[inputId(f)]||[])" :key="r.value" class="trade-check"><input v-bind="accessibility(f)" type="checkbox" :disabled="disabled||f.readonly" :checked="String(modelValue[f.key]||'').split(/[\s,，]+/).includes(r.value)" @change="toggleId(f,r.value,($event.target as HTMLInputElement).checked)"><span>{{r.label}}<code class="business-reference-id">{{r.value}}</code></span></label><p v-if="!(references?.[inputId(f)]||[]).length" class="business-muted">先读取本人获准使用的实际资料，或在本页上传本次材料。</p><button class="outline" type="button" :disabled="disabled||f.readonly||referenceBusy" @click="emit('read-reference',{field:f,context:modelValue,key:inputId(f)})">读取可选{{f.label}}</button></fieldset><label v-else-if="f.type==='boolean'" class="trade-check" :for="inputId(f)"><input v-bind="accessibility(f)" :id="inputId(f)" type="checkbox" :disabled="disabled||f.readonly" :checked="modelValue[f.key]===true" @change="change(f.key,($event.target as HTMLInputElement).checked)">{{f.label}}</label>
<fieldset v-bind="accessibility(f)" v-else-if="f.type==='values'" class="business-group"><legend>{{f.label}}</legend><label v-for="c in f.choices" :key="choice(c)" class="trade-check"><input v-bind="accessibility(f)" type="checkbox" :disabled="disabled||f.readonly" :checked="Array.isArray(modelValue[f.key])&&(modelValue[f.key] as string[]).includes(choice(c))" @change="toggle(f,choice(c),($event.target as HTMLInputElement).checked)">{{label(c)}}</label></fieldset>
<div v-else class="business-field"><label :for="inputId(f)">{{f.label}}<span v-if="f.nullable||f.optional" class="business-muted"> · 可留空</span><span v-if="f.type==='money'">（元）</span></label><output v-if="f.fixed!==undefined" :id="inputId(f)">{{typeof f.fixed==='boolean'?(f.fixed?'是':'否'):f.fixed===null?'不适用':f.fixed}}</output><textarea v-bind="accessibility(f)" v-else-if="['textarea','ids','numbers','lines'].includes(f.type||'')" :id="inputId(f)" :value="modelValue[f.key] as string" :disabled="disabled||f.readonly" :maxlength="f.type==='textarea'?f.max:undefined" :rows="f.type==='textarea'?4:2" @input="change(f.key,($event.target as HTMLTextAreaElement).value)"/><select v-bind="accessibility(f)" v-else-if="f.type==='select'" :id="inputId(f)" :value="modelValue[f.key]" :disabled="disabled||f.readonly" @change="change(f.key,($event.target as HTMLSelectElement).value)"><option value="">请选择</option><option v-for="c in f.choices" :key="choice(c)" :value="choice(c)">{{label(c)}}</option></select><select v-bind="accessibility(f)" v-else-if="f.type==='id'" :id="inputId(f)" :value="modelValue[f.key]" :disabled="disabled||f.readonly" @change="pick(f,$event)"><option value="">请选择当前获准记录</option><option v-if="modelValue[f.key]&&!(references?.[inputId(f)]||[]).some(r=>r.value===modelValue[f.key])" :value="modelValue[f.key] as string">原记录已关联（查看原约定核对）</option><option v-for="r in (references?.[inputId(f)]||[])" :key="r.value" :value="r.value">{{r.label}}</option></select><input v-bind="accessibility(f)" v-else :readonly="f.type==='hash'" :id="inputId(f)" :value="modelValue[f.key]" :disabled="disabled||f.readonly" :type="f.type==='datetime'?'datetime-local':'text'" :inputmode="['integer','money'].includes(f.type||'')?'decimal':undefined" :maxlength="f.max" :autocomplete="'off'" @input="change(f.key,($event.target as HTMLInputElement).value)"><button v-if="f.type==='id'&&!f.readonly" class="outline business-reference-read" type="button" :disabled="disabled||f.readonly||referenceBusy" @click="emit('read-reference',{field:f,context:modelValue,key:inputId(f)})">读取可选{{f.label}}</button><small v-if="f.type==='id'&&modelValue[f.key]" class="business-reference-value"><span>{{selectedReference(f)?.label||'当前关联编号，仍需读取核对'}}</span><code>{{modelValue[f.key]}}</code></small><small v-if="f.type==='hash'">从已读取原记录自动带入，重新确认本版内容。</small><small v-if="f.hint">{{f.hint}}</small><small v-else-if="f.type==='lines'">每行填写一项。</small></div>
<p v-if="errors?.[inputId(f)]" :id="`${inputId(f)}-error`" class="business-field-error" role="alert">{{errors?.[inputId(f)]}}</p></div></template></template>
